# filename: fraud_service/app/rules/card_rules.py

from datetime import datetime, timezone

from fraud_service.app.schemas.fraud import RuleResult


class CardRules:

    def check_expiry(self, exp_month: int, exp_year: int) -> RuleResult:
        now = datetime.now(tz=timezone.utc)
        if exp_year < now.year or (exp_year == now.year and exp_month < now.month):
            return RuleResult(
                rule_name="expired_card",
                triggered=True,
                score_impact=100,
                reason="Card is expired"
            )
        return RuleResult(rule_name="card_expiry", triggered=False, score_impact=0)

    def check_card_testing_pattern(self, amount: int, is_first_use: bool) -> RuleResult:
        if is_first_use and amount < 200:
            return RuleResult(
                rule_name="card_testing_pattern",
                triggered=True,
                score_impact=35,
                reason=f"Small amount ${amount/100:.2f} on first card use"
            )
        return RuleResult(rule_name="card_testing", triggered=False, score_impact=0)

    def get_exp_months_remaining(self, exp_month: int, exp_year: int) -> int:
        now = datetime.now(tz=timezone.utc)
        return max(0, (exp_year - now.year) * 12 + (exp_month - now.month))
